internal sealed interface SvgPathSegment {
    data class MoveTo(val x: Float, val y: Float) : SvgPathSegment
    data class CubicTo(
        val x1: Float, val y1: Float,
        val x2: Float, val y2: Float,
        val x3: Float, val y3: Float
    ) : SvgPathSegment
    data object Close : SvgPathSegment
}

private val parsedPathCache = java.util.concurrent.ConcurrentHashMap<String, List<SvgPathSegment>>()

internal fun parseSvgSegments(pathData: String): List<SvgPathSegment> {
    parsedPathCache[pathData]?.let { return it }
    val segments = ArrayList<SvgPathSegment>(96)
    var i = 0
    val n = pathData.length
    fun skipSep() { while (i < n && (pathData[i] == ' ' || pathData[i] == ',')) i++ }
    fun nextFloat(): Float {
        skipSep()
        val start = i
        if (i < n && (pathData[i] == '-' || pathData[i] == '+')) i++
        while (i < n && (pathData[i].isDigit() || pathData[i] == '.')) i++
        return pathData.substring(start, i).toFloat()
    }
    while (i < n) {
        skipSep()
        if (i >= n) break
        when (pathData[i]) {
            'M' -> { i++; segments += SvgPathSegment.MoveTo(nextFloat(), nextFloat()) }
            'C' -> { i++; segments += SvgPathSegment.CubicTo(nextFloat(), nextFloat(), nextFloat(), nextFloat(), nextFloat(), nextFloat()) }
            'Z' -> { i++; segments += SvgPathSegment.Close }
            else -> i++
        }
    }
    parsedPathCache[pathData] = segments
    return segments
}

internal fun buildScaledSvgPath(
    pathData: String,
    refWidth: Float,
    refHeight: Float,
    targetWidth: Float,
    targetHeight: Float
): Path {
    val sx = targetWidth / refWidth
    val sy = targetHeight / refHeight
    val path = Path()
    for (seg in parseSvgSegments(pathData)) {
        when (seg) {
            is SvgPathSegment.MoveTo -> path.moveTo(seg.x * sx, seg.y * sy)
            is SvgPathSegment.CubicTo -> path.cubicTo(
                seg.x1 * sx, seg.y1 * sy,
                seg.x2 * sx, seg.y2 * sy,
                seg.x3 * sx, seg.y3 * sy
            )
            SvgPathSegment.Close -> path.close()
        }
    }
    return path
}

internal class OrganicSvgShape(
    private val pathData: String,
    private val refWidth: Float,
    private val refHeight: Float
) : Shape {
    override fun createOutline(size: Size, layoutDirection: LayoutDirection, density: Density): Outline {
        return Outline.Generic(buildScaledSvgPath(pathData, refWidth, refHeight, size.width, size.height))
    }
}

